        // site tour
        tour_skip: 'Saltar el recorrido', tour_prev: 'Atrás', tour_next: 'Siguiente', tour_go: '¡Vamos!', tour_done: '¡A aprender!', tour_step: '{n} / {m}', tour_in_more: '(en el móvil, dentro de «Más»)', tour_replay: 'Recorrido del sitio', tour_replay_btn: '✨ Ver otra vez el recorrido', tour_welcome_title: '¡Hola! Soy 小花火 🎆', tour_welcome_text: '¡Bienvenido al Pequeño Mundo de Hanabi, un rincón para aprender idiomas juntos! Te enseño todo; solo lleva un minuto.', tour_goal_title: 'Lo de hoy', tour_goal_text: "Tus tareas de hoy, en orden, se marcan al terminarlas. El botón grande de abajo te lleva directo a la siguiente; toca el círculo para cambiar tu meta diaria de palabras.", tour_start_title: 'Empieza aquí', tour_start_text: 'Este botón te lleva directamente al siguiente paso que aún no has hecho.', tour_quiz_title: 'Quiz de vocabulario', tour_quiz_text: 'Todas las palabras del idioma que aprendes: «Temas» por situación (comida, transporte, viajes…) y «Niveles de examen» con las listas JLPT, TOPIK, HSK y MCER. Avanza nivel a nivel: 10 palabras cada uno, ¡con un 80 % lo pasas!', tour_review_title: 'Repaso y errores', tour_review_text: '«Repaso» te avisa de las palabras que estás a punto de olvidar; el número indica cuántas tarjetas toca repasar ahora. Tu libreta de errores también está aquí.', tour_dict_title: 'Diccionario', tour_dict_text: '¿No conoces una palabra? Búscala: traducción, categoría, significado y ejemplos, y también puedes escucharla.', tour_alphabet_title: 'Alfabeto', tour_alphabet_text: '¿Acabas de empezar un idioma? ¡Empieza por sus letras y sonidos! 8 idiomas, cada letra con una palabra de ejemplo.', tour_grammar_title: 'Gramática', tour_grammar_text: 'Gramática japonesa N5 y N4: explicación, puntos clave, errores frecuentes, ejemplos con audio y una pequeña práctica.', tour_notes_title: 'Bloc de notas', tour_notes_text: 'Guarda gramática, palabras, errores y capturas en carpetas y etiquetas. Marca ☆ para que te recuerde repasar; con sesión iniciada, se sincroniza.', tour_settings_title: 'Ajustes', tour_settings_text: 'Elige qué páginas mostrar y una voz para la pronunciación de cada idioma.', tour_lang_title: 'Idioma y modo oscuro', tour_lang_text: 'Puedes cambiar el sitio entre 9 idiomas (en el móvil: en el menú «Estoy aprendiendo» o «Idioma del sitio» en «Más»). El tema oscuro «墨夜» se activa justo al lado (en el móvil, en «Más»).', tour_done_title: '¡Todo listo!', tour_done_text: "¡Sigue aprendiendo y avanza hacia tus sueños! Para ver este recorrido otra vez, abre ☰ y elige «Recorrido del sitio».", tour_study_title: "Estudiar: gramática, lectura, comprensión auditiva", tour_study_text: "El menú Estudiar tiene gramática (cada punto con explicación, ejemplos y práctica), lectura por niveles (toca una frase para oírla, una palabra para ver su significado) y comprensión auditiva con el formato del JLPT, el TOPIK y el HSK, con exámenes de prueba.", tour_tools_title: "Herramientas y ajustes", tour_tools_text: "El menú Herramientas tiene el diccionario, el alfabeto (empieza por los sonidos) y el bloc de notas. Arriba a la derecha cambias el idioma del sitio (9 idiomas) y el modo oscuro, y ☰ tiene los ajustes y las novedades (en el móvil, todo está en «Más»).",
